import re
import json
import time
import os

# Step Functions task handler for email validation in user registration workflow
# This lambda validates user-submitted email addresses before proceeding to
# the account creation step in the state machine.

# Precompiled regex for comprehensive email validation per RFC 5322
# Handles quoted strings, nested comments, and IP literal addresses
EMAIL_REGEX = re.compile(
    r'^([a-zA-Z0-9]+([._+\-][a-zA-Z0-9]+)*)+@'
    r'(([a-zA-Z0-9]+([\-][a-zA-Z0-9]+)*)+\.)+[a-zA-Z]{2,63}$'
)

# Secondary validation for display name portion
DISPLAY_NAME_REGEX = re.compile(
    r'^[\w\s]*(([._\-]+[\w\s]*)*[._\-]+)*[\w\s]*$'
)

def validate_email(email_address):
    """Validate email format using comprehensive regex."""
    if not email_address or len(email_address) > 320:
        return False
    match = EMAIL_REGEX.match(email_address)
    return match is not None

def validate_display_name(name):
    """Validate display name characters."""
    if not name:
        return True  # display name is optional
    match = DISPLAY_NAME_REGEX.match(name)
    return match is not None

def process_batch(records):
    """Process a batch of registration records from the Step Functions Map state."""
    results = []
    for record in records:
        email = record.get('email', '')
        display_name = record.get('display_name', '')

        start = time.time()
        email_valid = validate_email(email)
        name_valid = validate_display_name(display_name)
        elapsed = time.time() - start

        results.append({
            'email': email,
            'email_valid': email_valid,
            'name_valid': name_valid,
            'processing_time_ms': round(elapsed * 1000, 2)
        })
    return results

def lambda_handler(event, context):
    """AWS Lambda handler invoked by Step Functions task state.

    Expected input from state machine:
    {
        "taskToken": "...",
        "records": [{"email": "...", "display_name": "..."}]
    }
    """
    try:
        records = event.get('records', [])
        if not records:
            return {
                'statusCode': 400,
                'body': json.dumps({'error': 'No records provided'})
            }

        # Process validation
        results = process_batch(records)

        valid_count = sum(1 for r in results if r['email_valid'] and r['name_valid'])

        response = {
            'statusCode': 200,
            'body': json.dumps({
                'total': len(results),
                'valid': valid_count,
                'invalid': len(results) - valid_count,
                'results': results
            })
        }

        # Log slow validations for monitoring
        slow_records = [r for r in results if r['processing_time_ms'] > 100]
        if slow_records:
            print(f"WARN: {len(slow_records)} records took >100ms to validate")
            for sr in slow_records:
                print(f"  Slow validation: {sr['email'][:20]}... took {sr['processing_time_ms']}ms")

        return response

    except Exception as e:
        print(f"ERROR: {str(e)}")
        return {
            'statusCode': 500,
            'body': json.dumps({'error': 'Internal validation error'})
        }

# Local testing
